-- Demonstração brasileira para uma cafeteria já cadastrada.
-- Não executa se o cardápio já tiver categorias ou produtos.
BEGIN;
-- Corrige a restrição antiga que não aceita a moeda brasileira.
ALTER TABLE menus DROP CONSTRAINT IF EXISTS menus_currency_check;
ALTER TABLE menus ADD CONSTRAINT menus_currency_check
  CHECK (currency IN ('TRY','USD','EUR','GBP','AZN','RUB','SAR','AED','BRL'));
DO $seed$
DECLARE target_menu uuid; target_business uuid; cat record; catid uuid; item record;
BEGIN
 SELECT m.id,m.business_id INTO target_menu,target_business
 FROM menus m JOIN businesses b ON b.id=m.business_id
 WHERE b.slug='cafe-com-amor'
 ORDER BY m.created_at ASC LIMIT 1;
 IF target_menu IS NULL THEN
  RAISE EXCEPTION 'Cardápio da cafeteria cafe-com-amor não encontrado';
 END IF;
 IF EXISTS(SELECT 1 FROM categories WHERE menu_id=target_menu) THEN
  RAISE NOTICE 'Cardápio já contém categorias; sem alteração de produtos.';
  RETURN;
 END IF;
 UPDATE menus SET name='Cardápio Principal',description='Um carinho a cada xícara',
  currency='BRL',currency_symbol='R$',default_language='pt',languages='["pt"]'::jsonb,
  theme='zarif',primary_color='#835533',font_family='lora'
 WHERE id=target_menu;
 FOR cat IN SELECT DISTINCT t.category,t.catpos FROM jsonb_to_recordset('[{"category":"Cafés especiais","catpos":0,"product":"Espresso","description":"Café intenso com crema dourada.","price":8,"image":"https://images.unsplash.com/photo-1510707577719-ae7c14805e3a?auto=format&fit=crop&w=700&q=80","position":0,"featured":true},{"category":"Cafés especiais","catpos":0,"product":"Espresso duplo","description":"Duas doses encorpadas de espresso.","price":12,"image":"https://images.unsplash.com/photo-1495474472287-4d71bcdd2085?auto=format&fit=crop&w=700&q=80","position":1,"featured":false},{"category":"Cafés especiais","catpos":0,"product":"Americano","description":"Espresso alongado com água quente.","price":10,"image":"https://images.unsplash.com/photo-1511920170033-f8396924c348?auto=format&fit=crop&w=700&q=80","position":2,"featured":false},{"category":"Cafés especiais","catpos":0,"product":"Café coado","description":"Café filtrado na hora.","price":9,"image":"https://images.unsplash.com/photo-1447933601403-0c6688de566e?auto=format&fit=crop&w=700&q=80","position":3,"featured":false},{"category":"Cafés especiais","catpos":0,"product":"Cappuccino artesanal","description":"Espresso, leite vaporizado e cacau.","price":15,"image":"https://images.unsplash.com/photo-1570968915860-54d5c301fa9f?auto=format&fit=crop&w=700&q=80","position":4,"featured":false},{"category":"Cafés especiais","catpos":0,"product":"Latte","description":"Espresso suave com leite cremoso.","price":14,"image":"https://images.unsplash.com/photo-1561882468-9110e03e0f78?auto=format&fit=crop&w=700&q=80","position":5,"featured":false},{"category":"Cafés especiais","catpos":0,"product":"Mocha","description":"Café, leite e chocolate.","price":18,"image":"https://images.unsplash.com/photo-1461023058943-07fcbe16d735?auto=format&fit=crop&w=700&q=80","position":6,"featured":false},{"category":"Cafés especiais","catpos":0,"product":"Chocolate quente","description":"Chocolate cremoso servido quentinho.","price":16,"image":"https://images.unsplash.com/photo-1542990253-0b8be29b14b8?auto=format&fit=crop&w=700&q=80","position":7,"featured":false},{"category":"Cafés gelados","catpos":1,"product":"Iced latte","description":"Espresso com leite e gelo.","price":16,"image":"https://images.unsplash.com/photo-1461023058943-07fcbe16d735?auto=format&fit=crop&w=700&q=80","position":0,"featured":true},{"category":"Cafés gelados","catpos":1,"product":"Café gelado","description":"Café especial servido sobre gelo.","price":15,"image":"https://images.unsplash.com/photo-1517701604599-bb29b565090c?auto=format&fit=crop&w=700&q=80","position":1,"featured":false},{"category":"Cafés gelados","catpos":1,"product":"Frappé de café","description":"Café batido com leite e gelo.","price":19,"image":"https://images.unsplash.com/photo-1572490122747-3968b75cc699?auto=format&fit=crop&w=700&q=80","position":2,"featured":false},{"category":"Cafés gelados","catpos":1,"product":"Affogato","description":"Sorvete de baunilha com espresso.","price":18,"image":"https://images.unsplash.com/photo-1551024506-0bccd828d307?auto=format&fit=crop&w=700&q=80","position":3,"featured":false},{"category":"Cafés gelados","catpos":1,"product":"Espresso tônica","description":"Espresso, água tônica e gelo.","price":17,"image":"https://images.unsplash.com/photo-1511920170033-f8396924c348?auto=format&fit=crop&w=700&q=80","position":4,"featured":false},{"category":"Salgados","catpos":2,"product":"Pão na chapa com amor","description":"Pão dourado na chapa com manteiga.","price":8,"image":"https://images.unsplash.com/photo-1509440159596-0249088772ff?auto=format&fit=crop&w=700&q=80","position":0,"featured":true},{"category":"Salgados","catpos":2,"product":"Pão de queijo","description":"Porção de pães de queijo quentinhos.","price":9,"image":"https://images.unsplash.com/photo-1608198093002-ad4e005484df?auto=format&fit=crop&w=700&q=80","position":1,"featured":false},{"category":"Salgados","catpos":2,"product":"Misto quente","description":"Pão 