 AS t(category text,catpos int,product text,description text,price numeric,image text,position int,featured boolean)
 ORDER BY t.catpos LOOP
  INSERT INTO categories(business_id,menu_id,translations,position,is_active)
  VALUES(target_business,target_menu,jsonb_build_object('pt',jsonb_build_object('name',cat.category)),cat.catpos,true)
  RETURNING id INTO catid;
  FOR item IN SELECT * FROM jsonb_to_recordset('[{"category":"Cafés especiais","catpos":0,"product":"Espresso","description":"Café intenso com crema dourada.","price":8,"image":"https://images.unsplash.com/photo-1510707577719-ae7c14805e3a?auto=format&fit=crop&w=700&q=80","position":0,"featured":true},{"category":"Cafés especiais","catpos":0,"product":"Espresso duplo","description":"Duas doses encorpadas de espresso.","price":12,"image":"https://images.unsplash.com/photo-1495474472287-4d71bcdd2085?auto=format&fit=crop&w=700&q=80","position":1,"featured":false},{"category":"Cafés especiais","catpos":0,"product":"Americano","description":"Espresso alongado com água quente.","price":10,"image":"https://images.unsplash.com/photo-1511920170033-f8396924c348?auto=format&fit=crop&w=700&q=80","position":2,"featured":false},{"category":"Cafés especiais","catpos":0,"product":"Café coado","description":"Café filtrado na hora.","price":9,"image":"https://images.unsplash.com/photo-1447933601403-0c6688de566e?auto=format&fit=crop&w=700&q=80","position":3,"featured":false},{"category":"Cafés especiais","catpos":0,"product":"Cappuccino artesanal","description":"Espresso, leite vaporizado e cacau.","price":15,"image":"https://images.unsplash.com/photo-1570968915860-54d5c301fa9f?auto=format&fit=crop&w=700&q=80","position":4,"featured":false},{"category":"Cafés especiais","catpos":0,"product":"Latte","description":"Espresso suave com leite cremoso.","price":14,"image":"https://images.unsplash.com/photo-1561882468-9110e03e0f78?auto=format&fit=crop&w=700&q=80","position":5,"featured":false},{"category":"Cafés especiais","catpos":0,"product":"Mocha","description":"Café, leite e chocolate.","price":18,"image":"https://images.unsplash.com/photo-1461023058943-07fcbe16d735?auto=format&fit=crop&w=700&q=80","position":6,"featured":false},{"category":"Cafés especiais","catpos":0,"product":"Chocolate quente","description":"Chocolate cremoso servido quentinho.","price":16,"image":"https://images.uns