unto.","price":18,"image":"https://images.unsplash.com/photo-1528735602780-2552fd46c7af?auto=format&fit=crop&w=700&q=80","position":2,"featured":false},{"category":"Salgados","catpos":2,"product":"Croissant de queijo","description":"Massa folhada com queijo cremoso.","price":19,"image":"https://images.unsplash.com/photo-1555507036-ab1f4038808a?auto=format&fit=crop&w=700&q=80","position":3,"featured":false},{"category":"Salgados","catpos":2,"product":"Empada de frango","description":"Massa delicada com recheio de frango.","price":12,"image":"https://images.unsplash.com/photo-1601050690597-df0568f70950?auto=format&fit=crop&w=700&q=80","position":4,"featured":false},{"category":"Salgados","catpos":2,"product":"Sanduíche natural","description":"Pão macio, folhas frescas e frango.","price":17,"image":"https://images.unsplash.com/photo-1553909489-cd47e0ef937f?auto=format&fit=crop&w=700&q=80","position":5,"featured":false},{"category":"Doces e sobremesas","catpos":3,"product":"Bolo do dia","description":"Fatia de bolo caseiro fresquinho.","price":12,"image":"https://images.unsplash.com/photo-1464305795204-6f5bbfc7fb81?auto=format&fit=crop&w=700&q=80","position":0,"featured":true},{"category":"Doces e sobremesas","catpos":3,"product":"Brownie de chocolate","description":"Brownie macio e rico em chocolate.","price":13,"image":"https://images.unsplash.com/photo-1606313564200-e75d5e30476c?auto=format&fit=crop&w=700&q=80","position":1,"featured":false},{"category":"Doces e sobremesas","catpos":3,"product":"Cookie de chocolate","description":"Cookie artesanal com gotas de chocolate.","price":8,"image":"https://images.unsplash.com/photo-1499636136210-6f4ee915583e?auto=format&fit=crop&w=700&q=80","position":2,"featured":false},{"category":"Doces e sobremesas","catpos":3,"product":"Cheesecake","description":"Fatia cremosa com calda de frutas.","price":18,"image":"https://images.unsplash.com/photo-1533134242443-d4fd215305ad?auto=format&fit=crop&w=700&q=80","position":3,"featured":fa