    AS t(category text,catpos int,product text,description text,price numeric,image text,position int,featured boolean)
    WHERE category=cat.category ORDER BY position LOOP
    INSERT INTO products(business_id,category_id,translations,price,image_url,position,is_featured,is_active)
    VALUES(target_business,catid,jsonb_build_object('pt',jsonb_build_object('name',item.product,'description',item.description)),
     item.price,item.image,item.position,item.featured,true);
  END LOOP;
 END LOOP;
END $seed$;
COMMIT;
